<script lang="ts">
import type { Snippet } from 'svelte';
import { untrack, tick, onMount, onDestroy } from 'svelte';
import type { RadioGroupContract } from '@unofficial-krds/contracts';
import { owned, control, resetField, ignoredKey } from './catalog-state.svelte.js';
let p: RadioGroupContract  = $props();
function validate(){const ids=p.options.map(option=>option.id).filter(id=>id!==undefined);if(ids.some(id=>!id?.trim())||new Set(ids).size!==ids.length)throw new TypeError('Explicit radio IDs must be unique and nonempty');}validate();$effect(validate);
const value=control<string|null>(()=>p.value,untrack(()=>p.defaultValue),null,value=>p.onValueChange?.({value}));const uid=$props.id();let root:HTMLFieldSetElement;function sync(){root?.querySelectorAll<HTMLInputElement>('input').forEach(input=>input.checked=input.value===value.value);}$effect(()=>{const values=p.options.map(o=>o.value);if(new Set(values).size!==values.length||value.value!==null&&!values.includes(value.value))throw new TypeError('Radio values must be unique and committed choice must exist');sync();});resetField(()=>root,()=>{value.reset();sync();});function changed(next:string){value.request(next);void tick().then(sync);}function keydown(e:KeyboardEvent){if(ignoredKey(e))return;const controls=[...root.querySelectorAll<HTMLInputElement>('input:not(:disabled)')];const i=controls.indexOf(document.activeElement as HTMLInputElement);if(i<0)return;let next=i;if(e.key==='Tab')next=i+(e.shiftKey?-1:1);else if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(e.key))next=e.key==='Home'?0:e.key==='End'?controls.length-1:(i+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)+controls.length)%controls.length;else return;if(next<0||next>=controls.length)return;e.preventDefault();controls[next].focus();if(e.key!=='Tab')changed(controls[next].value);}
</script>
<fieldset bind:this={root} id={p.id} disabled={p.disabled} {...owned('radio-group','root',p.invalid&&'invalid')} data-krds-size={p.size??'medium'} data-krds-appearance={p.appearance??'default'} aria-describedby={[p.helpId,p.invalid?p.errorId:undefined].filter(Boolean).join(' ')||undefined} onkeydown={keydown}><legend {...owned('radio-group','legend')}>{p.label}</legend>{#each p.options as option(option.value)}<label {...owned('radio-group','item',value.value===option.value?'checked':'unchecked',(p.disabled||option.disabled)&&'disabled',p.invalid&&'invalid')}><input id={option.id??`${uid}-${option.value}`} type="radio" name={p.name??uid} value={option.value} checked={value.value===option.value} disabled={option.disabled} required={p.required} {...owned('radio-group','control',value.value===option.value?'checked':'unchecked',(p.disabled||option.disabled)&&'disabled',p.invalid&&'invalid')} onchange={()=>changed(option.value)}/><span hidden aria-hidden="true" {...owned('radio-group','indicator',value.value===option.value?'checked':'unchecked')}></span><span {...owned('radio-group','label')}>{option.label}</span></label>{/each}</fieldset>
